// Build the hub-and-spoke nodes
let arch_apps = [
  "TrustGen", "Trust-Layer", "Pulse", "Trust Vault", "TL-Driver-Connect", "Orby",
  "GarageBot", "DarkWave Studios", "Trust Golf", "Orbit Staffing", "The Void", "Brew and Board",
  "VedaSolus", "Verdara", "Lume", "Paint Pros", "Trust Layer Hub", "Lot Ops Pro",
  "Signal Cast", "Chronicles", "DWSC", "LumeLine", "Guardian Screener", "Trust Home",
  "Trust book", "Arbora", "TLID", "The Arcade", "Trust Shield", "Driver",
  "Bomber Golf-3d", "Happy Eats - Lume", "Axiom", "Axiom Studio", "Lume-Cortex", "Meridian",
  "Verdara Ultra", "HydroCore", "Lume42", "Lume Auto", "Through the Veil", "Academy"
];

let arch_container = dom.create("div", { className: "arch-container" })

// Hub
dom.add_child(arch_container, dom.create("div", {
  className: "arch-hub",
  children: [
    dom.create("div", { className: "arch-hub-icon", text: "🛡️" }),
    dom.create("div", { className: "arch-hub-label", text: "Trust Layer" }),
    dom.create("div", { className: "arch-hub-label", styles: { fontSize: "0.5rem", opacity: "0.7", marginTop: "2px" }, text: "TLL" })
  ]
}))

// Rings (Percentages for responsive scaling)
let ring_pcts = [32, 60, 88];
for (let i = 0; i < ring_pcts.length; i++) {
  dom.add_child(arch_container, dom.create("div", {
    className: "arch-ring",
    styles: { width: ring_pcts[i] + "%", height: ring_pcts[i] + "%", animation: "orbit-pulse 4s ease infinite " + (i * 0.5) + "s" }
  }))
}

// Position nodes around rings (42 nodes: 6, 12, 24)
let ring_counts = [6, 12, 24];
let ring_index = 0;
let idx_on_ring = 0;

for (let i = 0; i < arch_apps.length; i++) {
  let app_name = arch_apps[i];
  
  if (idx_on_ring >= ring_counts[ring_index]) {
    ring_index++;
    idx_on_ring = 0;
  }
  
  let items_on_ring = ring_counts[ring_index];
  let radius_pct = ring_pcts[ring_index] / 2;
  
  // Offset angle slightly per ring for fractal appearance
  let angle_offset = ring_index * (Math.PI / items_on_ring);
  let angle = (idx_on_ring / items_on_ring) * 2 * Math.PI - (Math.PI / 2) + angle_offset;
  
  let cx = 50 + radius_pct * Math.cos(angle);
  let cy = 50 + radius_pct * Math.sin(angle);

  let node = dom.create("div", {
    className: "arch-node",
    styles: { left: cx + "%", top: cy + "%", transform: "translate(-50%, -50%)" },
    children: [
      dom.create("span", { className: "arch-tooltip", text: app_name })
    ]
  })
  dom.add_child(arch_container, node)
  idx_on_ring++;
}

let arch_section = dom.create("section", {
  id: "architecture",
  children: [
    dom.create("div", { className: "section-label reveal", text: "// ARCHITECTURE" }),
    dom.create("h2", { className: "section-title gradient-text reveal", text: "Ecosystem Architecture" }),
    dom.create("p", { className: "section-desc reveal", text: "The deterministic 42-node fractal engine governing the DWSC ecosystem. All applications connect through the Trust Layer and TLL — one unified deterministic governance structure." }),
    dom.create("div", { className: "reveal", children: [arch_container] })
  ]
})
